{
  "title": "Hepatitis C Adherence World",
  "perWatchSecond": 5,
  "levels": [
    {
      "kind": "hook",
      "finding": 0,
      "title": "Adherence threshold effect",
      "goal": "Show that higher transmission leads to more acute infections, implying that better adherence reduces spread.",
      "control": {
        "parameter": "beta1",
        "label": "Acute transmission rate",
        "lowEnd": "0.107",
        "highEnd": "0.428"
      },
      "watch": "peak of i (acutely infected)",
      "whatIf": {
        "prompt": "What if the acute transmission rate is doubled?",
        "parameter": "beta1",
        "value": 0.428
      },
      "difference": {
        "compartment": "i",
        "summary": "peak",
        "at": null,
        "time": 200,
        "relation": "higher",
        "by": 0.09
      },
      "effect": "The peak of acutely infected individuals is higher by more than 0.09.",
      "prediction": {
        "prompt": "Predict the effect of doubling the acute transmission rate on the peak of acute infections.",
        "claimed": "Higher by >0.09",
        "other": "Lower by >0.09"
      },
      "passage": {
        "title": "Headline result",
        "quote": "an adherence level exceeding 52% causes the reproduction number to drop below 1, curtailing further spread."
      },
      "carryForward": "Higher transmission makes the epidemic harder to control, so improving adherence is crucial."
    },
    {
      "kind": "idea",
      "finding": 3,
      "title": "Acute recovery speed",
      "goal": "Show that faster acute recovery reduces infection.",
      "control": {
        "parameter": "r2",
        "label": "Acute exit rate",
        "lowEnd": "0.0815",
        "highEnd": "0.326"
      },
      "watch": "peak of i",
      "whatIf": {
        "prompt": "What if the acute exit rate is halved?",
        "parameter": "r2",
        "value": 0.0815
      },
      "difference": {
        "compartment": "i",
        "summary": "peak",
        "at": null,
        "time": 200,
        "relation": "higher",
        "by": 0.06
      },
      "effect": "The peak of acutely infected individuals is higher by more than 0.06.",
      "prediction": {
        "prompt": "Predict the effect of halving the acute exit rate on the peak of acute infections.",
        "claimed": "Higher by >0.06",
        "other": "Lower by >0.06"
      },
      "passage": {
        "title": "Synergistic impact",
        "quote": "Our model unraveled the synergistic impact of simultaneously enhancing the recovery rate of acutely infected individuals and treatment adherence on reducing $ℛ_{0}$."
      },
      "carryForward": "Faster acute recovery together with good adherence helps suppress the epidemic."
    },
    {
      "kind": "method",
      "finding": 4,
      "title": "Quitters' transmission",
      "goal": "Show that increasing transmission from quitters raises their numbers.",
      "control": {
        "parameter": "beta3",
        "label": "Quitters' transmission",
        "lowEnd": "0.025",
        "highEnd": "0.1"
      },
      "watch": "peak of cq",
      "whatIf": {
        "prompt": "What if the transmission rate from quitters is doubled?",
        "parameter": "beta3",
        "value": 0.1
      },
      "difference": {
        "compartment": "cq",
        "summary": "peak",
        "at": null,
        "time": 200,
        "relation": "higher",
        "by": 0.009
      },
      "effect": "The peak of quitters is higher by more than 0.009.",
      "prediction": {
        "prompt": "Predict the effect of doubling quitters' transmission on their peak number.",
        "claimed": "Higher by >0.009",
        "other": "Lower by >0.009"
      },
      "passage": {
        "title": "Strongest influence",
        "quote": "$β_{3}$ exerts the strongest influence on the reproduction number."
      },
      "carryForward": "Quitters drive transmission, so keeping patients on treatment is vital."
    },
    {
      "kind": "evaluation",
      "finding": 5,
      "title": "Initial infection effect",
      "goal": "Show that a higher initial acute infection leads to sustained infection despite low R0.",
      "control": {
        "parameter": "i0",
        "label": "Initial acute infected",
        "lowEnd": "0.01",
        "highEnd": "0.05"
      },
      "watch": "i at t=200",
      "whatIf": {
        "prompt": "What if the initial acute infected proportion is increased to 0.05?",
        "parameter": "i0",
        "value": 0.05
      },
      "difference": {
        "compartment": "i",
        "summary": "at",
        "at": 200,
        "time": 200,
        "relation": "higher",
        "by": 0.02
      },
      "effect": "The acute infected proportion at t=200 is higher by more than 0.02.",
      "prediction": {
        "prompt": "Predict the effect of raising the initial acute infection to 0.05 on the infection level at t=200.",
        "claimed": "Higher by >0.02",
        "other": "Lower by >0.02"
      },
      "passage": {
        "title": "Backward bifurcation",
        "quote": "even if $ℛ_{0} < 1$, the disease may persist due to the coexistence of multiple stable equilibria."
      },
      "carryForward": "High initial infection can sustain the epidemic even with good adherence."
    },
    {
      "kind": "result",
      "finding": 6,
      "title": "Treatment recovery boost",
      "goal": "Show that raising the recovery rate on treatment reduces chronic infection.",
      "control": {
        "parameter": "rho",
        "label": "Recovery on treatment",
        "lowEnd": "0.053",
        "highEnd": "0.19"
      },
      "watch": "c at t=200",
      "whatIf": {
        "prompt": "What if the recovery rate on treatment is increased to 0.19?",
        "parameter": "rho",
        "value": 0.19
      },
      "difference": {
        "compartment": "c",
        "summary": "at",
        "at": 200,
        "time": 200,
        "relation": "lower",
        "by": 0.0005
      },
      "effect": "The chronically infected on treatment proportion at t=200 is lower by more than 0.0005.",
      "prediction": {
        "prompt": "Predict the effect of raising rho to 0.19 on chronic infection on treatment at t=200.",
        "claimed": "Lower by >0.0005",
        "other": "Higher by >0.0005"
      },
      "passage": {
        "title": "Recovery rate threshold",
        "quote": "When ρ approaches a value of approximately 0.19, we observe that $ℛ_{0}$ falls below 1."
      },
      "carryForward": "Improving treatment recovery helps push the epidemic below the threshold."
    }
  ],
  "limits": [
    "All worlds run for 200 years.",
    "Differences are at least a tenth of the chart height.",
    "Each level tests a distinct finding from the paper."
  ]
}
